{id:"TWK-313", q:"Indonesia menjadi anggota Perserikatan Bangsa-Bangsa pada tahun ....", opts:["1945","1949","1950","1955","1960"], a:2, ex:"Indonesia diterima menjadi anggota PBB pada tahun 1950."},
{id:"TWK-314", q:"Otonomi daerah diatur dalam UUD 1945 Pasal ....", opts:["Pasal 30","Pasal 33","Pasal 1","Pasal 18","Pasal 27"], a:3, ex:"Pasal 18 UUD 1945 mengatur pembagian daerah dan otonomi daerah."},
{id:"TWK-315", q:"Asas penyelenggaraan pemerintahan daerah meliputi ....", opts:["federalisme dan otonomi","otonomi dan medebewind saja","sentralisasi penuh","sentralisasi dan dekonsentrasi","desentralisasi, dekonsentrasi, dan tugas pembantuan"], a:4, ex:"Asas otonomi daerah: desentralisasi, dekonsentrasi, dan tugas pembantuan."},
{id:"TWK-316", q:"Ketahanan nasional adalah ....", opts:["kondisi dinamis berisi keuletan dan ketangguhan bangsa","cadangan devisa negara","jumlah penduduk produktif","luas wilayah negara","kekuatan angkatan bersenjata"], a:0, ex:"Ketahanan nasional adalah kondisi dinamis suatu bangsa berisi keuletan dan ketangguhan."},
{id:"TWK-317", q:"Geostrategi Indonesia diwujudkan melalui ....", opts:["politik bebas aktif","ketahanan nasional","wawasan nusantara","bela negara","otonomi daerah"], a:1, ex:"Geostrategi Indonesia diwujudkan melalui pembinaan ketahanan nasional."},
{id:"TWK-318", q:"Tujuh belas helai bulu pada masing-masing sayap Garuda Pancasila melambangkan ....", opts:["17 Agustus 1948","17 provinsi pertama","tanggal 17 kemerdekaan","17 sila Pancasila","17 pahlawan nasional"], a:2, ex:"Bulu Garuda: 17 helai di tiap sayap, 8 di ekor, 45 di leher melambangkan 17 Agustus 1945."},
{id:"TWK-319", q:"Perisai pada dada Garuda Pancasila melambangkan ....", opts:["persatuan suku bangsa","kekuatan militer","kekayaan alam","perjuangan dan perlindungan diri bangsa","kedaulatan pangan"], a:3, ex:"Perisai melambangkan perjuangan dan perlindungan diri dalam mencapai tujuan nasional."},
{id:"TWK-320", q:"Pita yang dicengkeram oleh Garuda Pancasila bertuliskan ....", opts:["Ing Ngarso Sung Tulodo","Bhineka Tunggal Ika Tan Hana Dharma Mangrwa","Satyameva Jayate","Tut Wuri Handayani","Bhinneka Tunggal Ika"], a:4, ex:"Pita pada kaki Garuda bertuliskan semboyan Bhinneka Tunggal Ika."},
{id:"TWK-321", q:"Kata baku dari 'cendikiawan' adalah ....", opts:["cendekiawan","cendikia","cendekya","cendikiawaan","cendikiawan"], a:0, ex:"Bentuk baku menurut KBBI adalah cendekiawan."},
{id:"TWK-322", q:"Kata baku dari 'ekstrim' adalah ....", opts:["ekstrim","ekstrem","extrim","extreme","ekstrimm"], a:1, ex:"Bentuk baku menurut KBBI adalah ekstrem."},
{id:"TWK-323", q:"Kata baku dari 'hirarki' adalah ....", opts:["hierarkhi","hirarki","hierarki","hierrarki","hirarkhi"], a:2, ex:"Bentuk baku menurut KBBI adalah hierarki."},
{id:"TWK-324", q:"Kata baku dari 'himbau' adalah ....", opts:["imbaau","himbauan","himbau","imbau","himbaau"], a:3, ex:"Bentuk baku menurut KBBI adalah imbau (mengimbau)."},
{id:"TWK-325", q:"Kata yang baku menurut KBBI adalah ....", opts:["ka'edah","kaidha","kaeddah","kaedah","kaidah"], a:4, ex:"Bentuk baku adalah kaidah, sedangkan kaedah tidak baku."},
{id:"TWK-326", q:"Penulisan yang baku adalah ....", opts:["narasumber","nara-sumber","naraSumber","nara sumbr","nara sumber"], a:0, ex:"Bentuk baku ditulis serangkai: narasumber."},
{id:"TWK-327", q:"Kata baku dari 'sistim' adalah ....", opts:["sistim","sistem","sistym","system","sistim"], a:1, ex:"Bentuk baku menurut KBBI adalah sistem."},
{id:"TWK-328", q:"Kata baku dari 'tehnik' adalah ....", opts:["teknig","tehnik","teknik","tekhnik","teqnik"], a:2, ex:"Bentuk baku menurut KBBI adalah teknik."},
{id:"TWK-329", q:"Kata baku dari 'merubah' adalah ....", opts:["mengubbah","merubah-rubah","merubah","mengubah","merobah"], a:3, ex:"Bentuk baku adalah mengubah (kata dasar ubah)."},
{id:"TWK-330", q:"Kata baku dari 'sekedar' adalah ....", opts:["sekedarnya","skedar","sekaadar","sekedar","sekadar"], a:4, ex:"Bentuk baku menurut KBBI adalah sekadar."},
{id:"TWK-331", q:"Berikut ini syarat kalimat efektif, KECUALI ....", opts:["keborosan","kecermatan","kelogisan","kesepadanan","kehematan"], a:0, ex:"Syarat kalimat efektif: kesepadanan, kehematan, kecermatan, kelogisan, dan kesatuan."},
{id:"TWK-332", q:"Kalimat 'Para hadirin sekalian dimohon berdiri' tidak efektif. Perbaikannya adalah ....", opts:["Para hadirin sekalian dimohon untuk berdiri","Hadirin dimohon berdiri","Para hadirin semuanya dimohon berdiri","Sekalian hadirin dimohon berdiri","Hadirin sekalian semuanya dimohon berdiri"], a:1, ex:"Kata 'para' sudah menunjukkan jamak sehingga 'sekalian' mubazir; cukup 'Hadirin dimohon berdiri.'"},
{id:"TWK-333", q:"Kalimat 'Demi untuk mencapai tujuan, kita harus bekerja keras' tidak hemat kata. Perbaikannya adalah ....", opts:["Demi untuk mencapai tujuannya kita kerja","Demi untuk mencapai tujuan, kita mesti kerja keras","Demi mencapai tujuan, kita harus bekerja keras","Untuk demi mencapai tujuan kita bekerja","Demi untuk tujuan kita harus bekerja"], a:2, ex:"'Demi untuk' boros; cukup 'Demi mencapai tujuan, kita harus bekerja keras.'"},
{id:"TWK-334", q:"Kalimat 'Adalah merupakan kewajiban kita menjaga kebersihan' tidak efektif karena ....", opts:["tidak logis","tidak ada objek","subjek ganda","pemakaian 'adalah merupakan' yang boros","tidak ada predikat"], a:3, ex:"'Adalah merupakan' boros; cukup 'Merupakan kewajiban kita menjaga kebersihan.'"},
{id:"TWK-335", q:"Kalimat 'Agar supaya cepat selesai, kerjakan bersama' tidak efektif. Perbaikannya adalah ....", opts:["Supaya agar cepat selesai dikerjakan","Agar supaya selesai cepat bersama","Supaya agar selesai, kerja bersama","Agar supaya cepat selesai, kerjakanlah bersama","Agar cepat selesai, kerjakan bersama"], a:4, ex:"'Agar supaya' boros; cukup 'Agar cepat selesai, kerjakan bersama.'"},
{id:"TWK-336", q:"Kalimat 'Ia naik ke atas panggung' tidak hemat kata karena ....", opts:["kata 'naik' sudah mengandung makna 'ke atas'","predikat ganda","tidak ada keterangan","susunan terbalik","subjek tidak jelas"], a:0, ex:"'Naik' sudah bermakna ke atas; cukup 'Ia naik ke panggung.'"},
{id:"TWK-337", q:"Penggunaan kata 'di mana' yang TIDAK baku sebagai penghubung adalah ....", opts:["Di mana kamu tinggal?","Kota di mana saya lahir sangat ramai","Di mana letak kantor pos?","Saya tidak tahu di mana dia","Di manakah kunci motor?"], a:1, ex:"'Di mana' tidak baku sebagai penghubung; seharusnya 'Kota tempat saya lahir sangat ramai.'"},
{id:"TWK-338", q:"Kalimat 'Mahasiswa yang rajin itu mereka lulus ujian' tidak efektif karena ....", opts:["tidak logis","tidak ada subjek","subjek ganda","tidak ada predikat","boros kata"], a:2, ex:"Subjek ganda ('mahasiswa...' dan 'mereka'); perbaikannya 'Mahasiswa yang rajin itu lulus ujian.'"},
{id:"TWK-339", q:"Kalimat 'Walaupun ia sakit tetapi ia tetap bekerja' tidak efektif karena ....", opts:["tidak hemat","tidak cermat","tidak ada subjek","konjungsi bertingkat yang ganda","tidak logis"], a:3, ex:"'Walaupun... tetapi' adalah konjungsi ganda; cukup 'Walaupun ia sakit, ia tetap bekerja.'"},
{id:"TWK-340", q:"Kalimat efektif dari segi kelogisan berarti ....", opts:["strukturnya lengkap","ejaannya benar","panjang dan rinci","kata-katanya indah","gagasan yang disampaikan dapat diterima akal sehat"], a:4, ex:"Kelogisan berarti gagasan dalam kalimat dapat diterima oleh akal sehat."},
{id:"TWK-341", q:"Undang-undang yang mengatur pertahanan negara adalah ....", opts:["UU No. 3 Tahun 2002","UU No. 23 Tahun 2019","UU No. 34 Tahun 2004","UU No. 2 Tahun 2002","UU No. 17 Tahun 1985"], a:0, ex:"Pertahanan negara diatur dalam UU No. 3 Tahun 2002."},
{id:"TWK-342", q:"Pengertian pertahanan negara menurut UU No. 3 Tahun 2002 adalah ....", opts:["kekuatan angkatan bersenjata semata","segala usaha untuk mempertahankan kedaulatan negara, keutuhan wilayah NKRI, dan keselamatan segenap bangsa","program wajib militer","strategi perang gerilya","pengamanan ibu kota negara"], a:1, ex:"Pertahanan negara adalah segala usaha mempertahankan kedaulatan, keutuhan wilayah NKRI, dan keselamatan bangsa."},
{id:"TWK-343", q:"Sistem pertahanan negara Indonesia disebut ....", opts:["sistem keamanan nasional","sistem pertahanan linier","sishankamrata","sistem pertahanan maritim","pertahanan berlapis"], a:2, ex:"Indonesia menganut Sishankamrata: sistem pertahanan dan keamanan rakyat semesta."},
{id:"TWK-344", q:"Komponen utama dalam sistem pertahanan negara adalah ....", opts:["hansip","satpam","Kepolisian","TNI","komponen cadangan"], a:3, ex:"Komponen utama pertahanan negara adalah Tentara Nasional Indonesia."},
{id:"TWK-345", q:"Komponen cadangan pertahanan negara terdiri atas ....", opts:["anggota Polri","pegawai negeri sipil","anggota DPR","anggota TNI aktif","warga negara yang disiapkan untuk dikerahkan"], a:4, ex:"Komponen cadangan adalah warga negara yang disiapkan untuk dikerahkan memperkuat komponen utama."},
{id:"TWK-346", q:"Komponen pendukung pertahanan negara terdiri atas ....", opts:["sumber daya nasional (SDM, SDA, sarana dan prasarana)","anggaran militer","pangkalan militer","aliansi luar negeri","senjata api"], a:0, ex:"Komponen pendukung adalah sumber daya nasional: SDM, SDA, serta sarana dan prasarana."},
{id:"TWK-347", q:"TNI terdiri atas tiga matra, yaitu ....", opts:["AD, Brimob, Polair","darat, laut, udara","infantri, kavaleri, artileri","kopassus, marinir, paskhas","kodam, koarmada, koopsau"], a:1, ex:"TNI terdiri atas TNI Angkatan Darat, Angkatan Laut, dan Angkatan Udara."},
{id:"TWK-348", q:"Fungsi TNI sebagai alat pertahanan negara meliputi penangkal, penindak, dan ....", opts:["penjaga","penyerang","pemulih","pengintai","penyusup"], a:2, ex:"Tiga fungsi TNI: penangkal, penindak, dan pemulih."},
{id:"TWK-349", q:"Kepolisian Negara Republik Indonesia merupakan alat negara di bidang ....", opts:["peradilan militer","penegak perda","pertahanan negara","keamanan dan ketertiban masyarakat","intelijen luar negeri"], a:3, ex:"Polri adalah alat negara di bidang keamanan dan ketertiban masyarakat (kamtibmas)."},
{id:"TWK-350", q:"Hak dan kewajiban warga negara dalam upaya pembelaan negara diatur dalam UUD 1945 Pasal ....", opts:["Pasal 28","Pasal 30 ayat (2)","Pasal 31","Pasal 34","Pasal 27 ayat (3)"], a:4, ex:"Pasal 27 ayat (3): setiap warga negara berhak dan wajib ikut serta dalam upaya pembelaan negara."},
{id:"TWK-351", q:"Bunyi Pasal 30 ayat (1) UUD 1945 adalah ....", opts:["Tiap-tiap warga negara berhak dan wajib ikut serta dalam usaha pertahanan dan keamanan negara","Kepolisian sebagai alat negara","Presiden memegang kekuasaan tertinggi atas angkatan perang","Pertahanan negara diatur dengan undang-undang","TNI terdiri atas AD, AL, AU"], a:0, ex:"Pasal 30 ayat (1): tiap warga negara berhak dan wajib ikut serta dalam usaha pertahanan dan keamanan negara."},
{id:"TWK-352", q:"Nilai-nilai dasar bela negara meliputi cinta tanah air, sadar berbangsa dan bernegara, setia pada Pancasila, rela berkorban, dan ....", opts:["kekayaan materi","kemampuan awal bela negara","kekuatan fisik","kepemilikan senjata","jabatan publik"], a:1, ex:"Lima nilai dasar bela negara: cinta tanah air, sadar berbangsa-bernegara, setia Pancasila, rela berkorban, kemampuan awal bela negara."},
{id:"TWK-353", q:"Contoh sikap bela negara bagi pelajar di lingkungan sekolah adalah ....", opts:["tawuran antarpelajar","membolos saat upacara","mengikuti upacara bendera dengan khidmat dan menaati tata tertib","mencontek saat ujian","merusak fasilitas sekolah"], a:2, ex:"Bela negara bagi pelajar antara lain mengikuti upacara dengan khidmat dan menaati tata tertib sekolah."},
{id:"TWK-354", q:"Contoh bela negara secara nonfisik bagi warga negara adalah ....", opts:["mengikuti wajib militer","berdemonstrasi","ikut latihan menembak","membayar pajak tepat waktu","menjadi tentara"], a:3, ex:"Membayar pajak tepat waktu adalah bentuk bela negara nonfisik."},
{id:"TWK-355", q:"Ancaman terhadap kedaulatan negara dibedakan menjadi ancaman militer dan ....", opts:["ancaman budaya","ancaman politik","ancaman siber saja","ancaman ekonomi","ancaman nonmiliter (nirmiliter)"], a:4, ex:"Ancaman dibedakan menjadi ancaman militer dan ancaman nonmiliter (nirmiliter)."},
{id:"TWK-356", q:"Hari Bela Negara diperingati setiap tanggal ....", opts:["19 Desember","20 Mei","1 Oktober","17 Agustus","10 November"], a:0, ex:"Hari Bela Negara diperingati setiap 19 Desember."},
{id:"TWK-357", q:"Hari Bela Negara ditetapkan untuk mengenang peristiwa ....", opts:["Serangan Umum 1 Maret","berdirinya Pemerintah Darurat RI di Bukittinggi","Proklamasi Kemerdekaan","Pertempuran Surabaya","Agresi Militer Belanda I"], a:1, ex:"19 Desember 1948 mengenang berdirinya PDRI di Bukittinggi saat Agresi Militer Belanda II."},
{id:"TWK-358", q:"Pemerintah Darurat Republik Indonesia (PDRI) dipimpin oleh ....", opts:["Soekarno","Moh. Hatta","Syafruddin Prawiranegara","Sutan Sjahrir","Amir Sjarifuddin"], a:2, ex:"PDRI dipimpin oleh Syafruddin Prawiranegara."},
{id:"TWK-359", q:"Sishankamrata melibatkan ....", opts:["pemerintah pusat","komponen cadangan","TNI saja","seluruh warga negara, wilayah, dan sumber daya nasional","Polri dan TNI"], a:3, ex:"Sishankamrata melibatkan seluruh warga negara, wilayah, dan sumber daya nasional secara total dan terpadu."},
{id:"TWK-360", q:"Panglima TNI diangkat dan diberhentikan oleh Presiden dengan persetujuan ....", opts:["MA","Wantimpres","DPD","MPR","DPR"], a:4, ex:"Pengangkatan dan pemberhentian Panglima TNI oleh Presiden memerlukan persetujuan DPR."}
